package net.civeira.phylax.common.security;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Observes;
import lombok.RequiredArgsConstructor;

@ApplicationScoped
@RequiredArgsConstructor
public class RbacAuthorizationDecisionListener {
  private final Rbac rbac;

  public void checkAuthorization(@Observes AuthorizationDecision event) {
    event.map(allow -> {
      if (allow.isAllowed()) {
        return rbac.checkAllow(event.getActor(), event.resourceName(), event.actionName());
      } else {
        return allow;
      }
    });
  }

  public void checkProperties(@Observes PropertiesProposal event) {
    event.add(rbac.inaccessibleFields(event.getActor(), event.resourceName(), event.viewName()));
  }
}
